\title{Plethystic Triviality of the Shifted $t$-Schur Basis}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}

\begin{abstract}
We study a one-parameter deformation of the Schur $Q$-functions, the \emph{shifted
$t$-Schur functions} $S^t_\lambda$, obtained by running the neutral-fermion
vertex-operator construction with $t$-deformed odd power sums. Working over the
rational function field $\KK=\Q(t)$ in the ring $\Lam=\KK[p_1,p_3,p_5,\dots]$ of
symmetric functions in the odd power sums, we prove that the entire deformation is
implemented by a single plethystic substitution $\phit\colon p_n\mapsto(1-t^n)p_n$
(for odd $n$): for every strict partition $\lambda$, $S^t_\lambda=\phit(Q_\lambda)$.
We show $\phit$ is an algebra automorphism with explicit inverse
$\psit\colon p_n\mapsto p_n/(1-t^n)$, hence the change of basis is invertible
($Q_\lambda=\psit(S^t_\lambda)$) and $\{S^t_\lambda\}$ is $\KK$-linearly independent
iff $\{Q_\lambda\}$ is. We sharpen ``trivial'' to mean automorphic, not identity, by
exhibiting $\phit(p_1)=(1-t)p_1\ne p_1$. Finally we situate $\phit$ inside the
\emph{diagonal plethysm group} $(\KK^\times)^{\Nat}\hookrightarrow\Aut_\KK(\Lam)$ of
monomial-diagonal operators $\diag_a\colon p_{2k+1}\mapsto a_k\,p_{2k+1}$, prove the
sharp dichotomy that $\diag_a$ is injective iff every $a_k\ne0$, and identify
$\phit=\diag_{(1-t^{2k+1})_k}$ as a member of the non-vanishing locus that
degenerates exactly at $t=1$. All results have been formalized and machine-checked.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
A recurring question for parametrized families of symmetric functions is whether a
family genuinely generalizes a classical basis or merely relabels it. The
Hall--Littlewood and Macdonald polynomials are deep deformations: their transition
matrices to the power-sum basis are not diagonal, and the $t$- (or $q,t$-)
dependence encodes substantial new combinatorics. At the opposite extreme are
\emph{plethystic substitutions} $p_n\mapsto f(t)\,p_n$, which rescale each power-sum
generator independently and are diagonal in the power-sum monomial basis; such a
substitution can never mix monomials, so any family it produces from a known basis
is structurally equivalent to that basis whenever the factors are invertible.

The \emph{shifted $t$-Schur functions} $S^t_\lambda$ are a deformation of the Schur
$Q$-functions $Q_\lambda$ built from the same vertex-operator data with $t$-deformed
odd power sums. Their definition does not, on its face, present them as plethysms of
$Q_\lambda$. We prove that the deformation is exactly the plethysm
$p_n\mapsto(1-t^n)p_n$, establish its invertibility and linear-algebraic
consequences, and locate it within the ambient group of diagonal plethysms.

\subsubsection*{Background on Schur $Q$-functions}
The Schur $Q$-functions form a distinguished basis of the subring $\Gamma$ of
symmetric functions generated by the odd power sums. They are the
symmetric-function avatar of the projective (spin) representation theory of the
symmetric and alternating groups: where ordinary Schur functions encode linear
characters of $S_n$, the $Q_\lambda$ (indexed by strict partitions) encode spin
characters. They also represent Schubert classes on the maximal isotropic
Grassmannian and arise from the boson--fermion correspondence for neutral free
fermions, the route taken here. The odd-power-sum presentation
$\Gamma=\KK[p_1,p_3,p_5,\dots]$ is exactly what makes $p_n\mapsto(1-t^n)p_n$ a
well-defined endomorphism, acting directly on algebraically independent
generators.

\subsection{Summary of results}
\begin{enumerate}
  \item Main identity (Thm.~\ref{thm:main}): $S^t_\lambda=\phit(Q_\lambda)$.
  \item Automorphism (Thm.~\ref{thm:auto}): $\phit$ is an automorphism with inverse $\psit$.
  \item Invertible change of basis (Thm.~\ref{thm:inv}): $Q_\lambda=\psit(S^t_\lambda)$.
  \item Basis triviality (Thm.~\ref{thm:li}): $\{S^t_{g(i)}\}$ is linearly independent iff $\{Q_{g(i)}\}$ is.
  \item Non-triviality boundary (Prop.~\ref{prop:nonid}): $\phit\ne\id$.
  \item Diagonal plethysm group (\S\ref{sec:group}): faithfulness, the injectivity dichotomy, and the placement of $\phit$.
\end{enumerate}

\section{Preliminaries}

\subsection{The odd power-sum ring}
Let $\KK=\Q(t)$ be the field of rational functions in a transcendental $t$. We model
the ring of symmetric functions in the odd power sums as the polynomial ring
\[
\Lam:=\KK[X_0,X_1,X_2,\dots],\qquad X_k\leftrightarrow p_{2k+1},
\]
(formally \texttt{MvPolynomial}\ $\Nat\,\KK$), where $X_k$ stands for the odd power
sum $p_{2k+1}$. Since the odd power sums are algebraically independent over $\KK$,
this is a faithful model of $\Gamma_\KK=\KK[p_1,p_3,p_5,\dots]$. We grade $\Lam$ by
$\deg X_k=2k+1$.

\subsection{Strict partitions}
A \emph{strict partition} is a finite strictly decreasing sequence of positive
integers $\lambda=(\lambda_1>\cdots>\lambda_\ell>0)$, represented as a list of its
parts. Schur $Q$-functions are indexed by strict partitions.

\subsection{The scaling scalars}
For $k\in\Nat$ set $\cc(k):=1-t^{2k+1}\in\KK$.

\begin{lemma}[\texttt{cc\_ne}]\label{lem:ccne}
For every $k$, $\cc(k)\ne0$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $1-t^{2k+1}=\iota(1-X^{2k+1})$ with $\iota\colon\Q[X]\hookrightarrow\Q(X)$ the
fraction-field embedding. Since $\Q(t)$ is the fraction field of the domain $\Q[t]$,
$\iota(g)=0$ iff $g=0$; and $1-X^{2k+1}\ne0$ since its value at $X=0$ is $1$.
\end{proof}

\section{The vertex-operator construction}
The construction is non-circular: $S^t_\lambda$ is built from $t$-deformed data and
is not defined as $\phit(Q_\lambda)$.

\begin{definition}[\texttt{phiT}]
$\phit\colon\Lam\to\Lam$ is the $\KK$-algebra endomorphism with
$\phit(X_k)=\cc(k)X_k=(1-t^{2k+1})X_k$; i.e.\ the plethysm $p_n\mapsto(1-t^n)p_n$.
\end{definition}

\subsection{Creation (one-row) functions}
The one-row functions $q_n=Q_{(n)}$ satisfy the Newton recursion
\[
q_0=1,\qquad n\,q_n=\sum_{0\le 2k\le n-1}2\,p_{2k+1}\,q_{\,n-1-2k}.
\]
The classical $q_n$ (\texttt{q}) use coefficient $cf(k)=X_k$; the $t$-deformed
$q^t_n$ (\texttt{qt}) use $cf(k)=\cc(k)X_k$.

\begin{lemma}[\texttt{qt\_eq\_phiT\_q}]\label{lem:qt}
For all $n$, $q^t_n=\phit(q_n)$.
\end{lemma}
\begin{proof}[Proof sketch]
Strong induction on $n$; apply the algebra map $\phit$ to the classical recursion,
turning each $p_{2k+1}$ into $\cc(k)X_k$, exactly the deformed coefficient.
\end{proof}

\subsection{Annihilation operators}
The annihilation map $\ann_d\colon\Lam\to\Lam[u]$ (\texttt{annGen}) is the algebra
map $X_k\mapsto X_k-d(k)u^{2k+1}$. Take $d\equiv4$ (\texttt{annShift}) classically
and $d(k)=4/\cc(k)$ (\texttt{annShiftT}) for the deformation.

\begin{lemma}[\texttt{annShiftT\_phiT}]\label{lem:ann}
For all $f$, $\ann^t(\phit f)=(\ann f).\mathrm{map}(\phit)$.
\end{lemma}
\begin{proof}[Proof sketch]
Both sides are algebra maps in $f$; check on $X_k$, where the constant $4/\cc(k)$
matches the $u^{2k+1}$ terms, using $\cc(k)\ne0$.
\end{proof}

\subsection{Vertex components and symmetric functions}
For $qf\colon\Nat\to\Lam$ set $T_{qf,n}(P)=\sum_m qf(n+m)\cdot[\mathrm{coeff}_m P]$.
Define $B_n(f)=T_{q,n}(\ann f)$ and $B^t_n(f)=T_{q^t,n}(\ann^t f)$, and
\[
Q_\lambda=B_{\lambda_1}\!\big(\cdots B_{\lambda_\ell}(1)\big),\qquad
S^t_\lambda=B^t_{\lambda_1}\!\big(\cdots B^t_{\lambda_\ell}(1)\big).
\]

\begin{lemma}[\texttt{Tsum\_map\_phiT}]\label{lem:tsum}
$T_{q^t,n}\big(P.\mathrm{map}(\phit)\big)=\phit\big(T_{q,n}(P)\big)$.
\end{lemma}
\begin{proof}[Proof sketch]
Expand over the support of $P$; use $q^t_{n+m}=\phit(q_{n+m})$
(Lemma~\ref{lem:qt}) and that $\phit$ commutes with the coefficient-wise product
and finite sum.
\end{proof}

\begin{lemma}[Intertwining, \texttt{Bt\_phiT}]\label{lem:bt}
$B^t_n(\phit f)=\phit(B_n f)$ for all $n,f$.
\end{lemma}
\begin{proof}[Proof sketch]
$B^t_n(\phit f)=T_{q^t,n}(\ann^t(\phit f))=T_{q^t,n}((\ann f).\mathrm{map}(\phit))
=\phit(T_{q,n}(\ann f))=\phit(B_n f)$, by Lemmas~\ref{lem:ann},~\ref{lem:tsum}.
\end{proof}

\section{The main identity}

\begin{theorem}[\texttt{Sfun\_eq\_phiT\_Qfun}, \texttt{shifted\_tSchur\_eq\_phiT\_Q}]\label{thm:main}
For every list of parts $\lambda$ (in particular every strict partition),
\[
S^t_\lambda=\phit(Q_\lambda).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Induct on the list. Empty: $1=\phit(1)$. For $\lambda=(a,\mu)$,
$S^t_\lambda=B^t_a(S^t_\mu)=B^t_a(\phit Q_\mu)=\phit(B_aQ_\mu)=\phit(Q_\lambda)$ by
induction and the intertwining Lemma~\ref{lem:bt}.
\end{proof}

This headline is falsifiable by coefficient comparison in the finite odd-power-sum
ring up to total degree $|\lambda|$.

\subsection{Worked example $\lambda=(1)$}
\begin{lemma}[\texttt{Qfun\_singleton}, \texttt{Sfun\_singleton}]\label{lem:single}
$Q_{(1)}=2p_1$ and $S^t_{(1)}=2(1-t)p_1=(1-t)Q_{(1)}$.
\end{lemma}
\begin{proof}[Proof sketch]
$B_1(1)$ gives $q_1=2p_1$, so $Q_{(1)}=2X_0$; then
$S^t_{(1)}=\phit(2X_0)=2\cc(0)X_0=2(1-t)X_0$.
\end{proof}

\section{Triviality: invertibility and consequences}

\begin{definition}[\texttt{dd}, \texttt{psiT}]
Set $\dd(k)=1/\cc(k)$ and $\psit(X_k)=\dd(k)X_k=\dfrac{1}{1-t^{2k+1}}X_k$.
\end{definition}

\begin{theorem}[\texttt{phiTEquiv}]\label{thm:auto}
$\phit$ is a $\KK$-algebra automorphism of $\Lam$ with two-sided inverse $\psit$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:ccne} each $\cc(k)$ is a unit, so $\dd(k)\cc(k)=1$; check on
generators that both composites act as the identity and apply \texttt{algHom\_ext}.
\end{proof}

\begin{theorem}[\texttt{Qfun\_eq\_psiT\_Sfun}]\label{thm:inv}
For every $\lambda$, $Q_\lambda=\psit(S^t_\lambda)$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply $\psit$ to Theorem~\ref{thm:main} and use $\psit\circ\phit=\id$.
\end{proof}

\begin{theorem}[Basis triviality, \texttt{linearIndependent\_Sfun\_iff}]\label{thm:li}
For any family $g\colon\iota\to\{\text{partitions}\}$, $\{S^t_{g(i)}\}_i$ is
$\KK$-linearly independent iff $\{Q_{g(i)}\}_i$ is.
\end{theorem}
\begin{proof}[Proof sketch]
$\phit$ is a linear automorphism (Thm.~\ref{thm:auto}) and
$S^t_{g(i)}=\phit(Q_{g(i)})$; transfer linear independence along $\phit$ and its
inverse, using that an automorphism has trivial kernel.
\end{proof}

\begin{proposition}[\texttt{phiT\_X\_zero\_ne}, \texttt{phiT\_ne\_id}]\label{prop:nonid}
$\phit(p_1)=(1-t)p_1\ne p_1$, hence $\phit\ne\id$.
\end{proposition}
\begin{proof}[Proof sketch]
Evaluate at $X\mapsto1$: $\phit(X_0)=X_0$ would force $1-t=1$, i.e.\ $t=0$,
contradicting $t\ne0$ in $\Q(t)$.
\end{proof}

\begin{remark}[Structural refinements]
\texttt{phiT\_monomial\_pow}: $\phit(X_k^m)=\cc(k)^m X_k^m$, so $\phit$ scales each
monomial $\prod_k X_k^{d_k}$ by $\prod_k\cc(k)^{d_k}$ and never mixes monomials.
\texttt{phiT\_isHomogeneous}: $\phit$ preserves the grading, the operator shadow of
$|S^t_\lambda|=|\lambda|=|Q_\lambda|$.
\end{remark}

\section{The diagonal plethysm group}\label{sec:group}
Work over an arbitrary field $\KK$ with $\Lam_\KK=\KK[X_0,X_1,\dots]$.

\begin{definition}[\texttt{diagHom}]
For $a\colon\Nat\to\KK$, the diagonal plethysm operator $\diag_a$ is the algebra
endomorphism $\diag_a(X_k)=a_k X_k$. Equivalently
$\diag_a(\prod_k X_k^{d_k})=\big(\prod_k a_k^{d_k}\big)\prod_k X_k^{d_k}$.
\end{definition}

\begin{proposition}[\texttt{diagHom\_one}, \texttt{diagHom\_comp}]\label{prop:func}
$\diag_1=\id$ and $\diag_a\circ\diag_b=\diag_{a\cdot b}$ (pointwise product).
\end{proposition}

\begin{theorem}[Faithfulness, \texttt{diagHom\_param\_injective}]\label{thm:faith}
The map $a\mapsto\diag_a$ is injective.
\end{theorem}
\begin{proof}[Proof sketch]
If $\diag_a=\diag_b$, then $a_kX_k=b_kX_k$, so $(C(a_k)-C(b_k))X_k=0$; since $X_k$
is not a zero divisor and $C$ is injective, $a_k=b_k$.
\end{proof}

\begin{theorem}[Dichotomy, \texttt{diagHom\_injective\_iff}, \texttt{diagEquiv}, \texttt{diagHom\_not\_injective\_of\_zero}]\label{thm:dich}
$\diag_a$ is injective iff $a_k\ne0$ for all $k$. If so, it is an automorphism with
inverse $\diag_{a^{-1}}$; if some $a_k=0$ then $\diag_a(X_k)=0$ while $X_k\ne0$.
\end{theorem}
\begin{proof}[Proof sketch]
($\Leftarrow$) take $b_k=a_k^{-1}$ and apply Proposition~\ref{prop:func}.
($\Rightarrow$) contrapositive is the collapse $X_k\mapsto0$.
\end{proof}

\begin{theorem}[\texttt{diagGroupHom}, \texttt{diagGroupHom\_injective}]
The assignment $a\mapsto\diag_a$ restricts to an injective group homomorphism
$(\KK^\times)^{\Nat}\to\Aut_\KK(\Lam_\KK)$, a faithful copy of $(\KK^\times)^{\Nat}$.
\end{theorem}

\subsection{The shifted $t$-Schur operator as a group member}
\begin{proposition}[\texttt{phiT\_eq\_diagHom}, \texttt{phiT\_injective}]
Over $\KK=\Q(t)$ with $\cc(k)=1-t^{2k+1}$, $\phit=\diag_{\cc}$ is injective because
each $\cc(k)\ne0$ (Lemma~\ref{lem:ccne}) places it in the non-vanishing locus.
\end{proposition}

\begin{proposition}[\texttt{ccAt}, \texttt{ccAt\_one\_eq\_zero}, \texttt{phiT\_specialize\_one\_not\_injective}]
Specializing $t\mapsto1$ sends every $\cc(k)$ to $0$; the resulting operator
collapses each generator and is not injective.
\end{proposition}

This pins the isomorphism to the generic point: $\phit$ is an automorphism precisely
because $t$ avoids the roots of $1-t^{2k+1}$, and triviality fails at $t=1$.

\section{Algorithms}
The results are effective. (i) Compute $q_n$ via the $O(n^2)$ Newton recursion of
\S3.2. (ii) Assemble $Q_\lambda$, $S^t_\lambda$ by applying $B_{\lambda_i}$ (resp.\
$B^t_{\lambda_i}$) right to left. (iii) Falsification test: compute both sides of
Theorem~\ref{thm:main} in the truncated ring and compare all monomial coefficients
as rational functions in $t$.

\section{Applications and discussion}
\textbf{Transport of identities.} As $\phit$ is diagonal and degree-preserving,
identities for $Q_\lambda$ transport to $S^t_\lambda$ by $p_n\mapsto(1-t^n)p_n$ with
$t$-dependence as products of $1-t^n$. \textbf{A diagnostic.} The diagonal plethysm
group tests whether a deformation is cosmetic: Hall--Littlewood/Macdonald are not
members; the shifted $t$-Schur deformation is. \textbf{Meaning of ``trivial.''}
Plethystic triviality is automorphic equivalence, not identity
(Prop.~\ref{prop:nonid}). \textbf{Computational consequence.} As $\phit,\psit$
are explicit on generators, $S^t_\lambda$ is obtained from the classical
$Q_\lambda$ by a single diagonal-scaling pass, and recovered exactly by $\psit$
since each factor is a unit. \textbf{Graded structure.} On each degree-$|\lambda|$
piece, $\phit$ is the diagonal matrix with entries $\prod_k\cc(k)^{d_k}$ over
monomials $X^d$, whose product (the determinant) factors into the cyclotomic-type
terms $1-t^{2k+1}$.

\section{Future directions}
\begin{enumerate}
  \item \emph{Orbit characterization.} For any unit sequence $c$, define
    $S^c_\lambda=\diag_c(Q_\lambda)$; conjecture Theorem~\ref{thm:li} generalizes
    verbatim with $\phit$ replaced by any $\diag_c$.
  \item \emph{Two-parameter deformation.} Over $\Q(q,t)$ the scalar
    $(1-t^{2k+1})/(1-q^{2k+1})$ is a unit; the resulting $\diag$ is again trivial,
    with fixed subalgebra the scalars iff $q\ne t$.
  \item \emph{Spectral rigidity.} Conjecture the centralizer of $\phit$ in
    $\Aut_\KK(\Lam)$ is exactly the diagonal plethysm group.
  \item \emph{Degree-graded determinant.} Conjecture
    $\det(\phit|_{X^d:\,\sum d_k(2k+1)=m})=\prod_{|d|=m}\prod_k(1-t^{2k+1})^{d_k}$.
  \item \emph{Specialization boundary.} Characterize the degeneration locus where
    some $1-t^{2k+1}$ becomes a zero divisor and triviality fails.
\end{enumerate}

\section{Conclusion}
The shifted $t$-Schur basis is plethystically trivial: the image of the Schur $Q$
basis under $p_n\mapsto(1-t^n)p_n$, an automorphism that is monomial-diagonal,
degree-preserving, and genuinely non-identity, sitting in the non-vanishing locus of
the diagonal plethysm group $(\KK^\times)^{\Nat}$ and degenerating exactly at $t=1$.
All results have been formally verified.

