function Q_ONE_ROW(cf, n_max):
    q[0] <- 1
    for n from 1 to n_max:
        acc <- 0
        k <- 0
        while 2*k <= n - 1:
            acc <- acc + 2 * cf(k) * q[n - 1 - 2*k]
            k <- k + 1
        q[n] <- acc / n
    return q
